const css='min-h-11 w-full min-w-0 scroll-mt-20';
const expiry=()=>new Date(Date.now()+7*86400000).toISOString();
const lines=(value:FormDataEntryValue|null)=>String(value??'').split('\n').map(line=>line.trim()).filter(Boolean);
